<template>
  <view :data-loading="loading?'true':'false'" :class="['xr-screen','xr-page-'+page,{'xr-has-tabs':isTab,'xr-has-dock':!isTab,'xr-native':nativeDevice}]">
    <view class="xr-header" :style="{paddingTop:nativeDevice?statusBar+'px':'0px'}">
      <view :class="['xr-header-inner',{'xr-header-brand':brandHeader}]">
        <button v-if="!isTab" class="xr-icon-button xr-back" aria-label="返回" @click="back"><UiIcon name="back" :size="40"/></button>
        <BrandMark :name="brandName" :logo="config.brandLogo" :subtitle="config.brandTagline" v-if="brandHeader" compact/>
        <text v-else class="xr-header-title">{{title}}</text>
        <!-- #ifdef H5 -->
        <view class="xr-wechat-capsule" aria-hidden="true"><text>•••</text><view/><text>⊙</text></view>
        <!-- #endif -->
      </view>
    </view>

    <view v-if="error" class="xr-error-banner" role="alert"><UiIcon name="cloud-off" tone="rose" :size="32"/><text>{{error}}</text><button class="xr-text-button" :disabled="loading" @click="refresh">重试</button></view>
    <view v-if="loading&&!products.length" class="xr-loading" aria-label="正在加载"><view class="xr-skeleton xr-skeleton-banner"/><view v-for="n in 3" :key="n" class="xr-skeleton xr-skeleton-row"/></view>

    <template v-if="page==='home'">
      <view class="xr-home-hero">
        <picker class="xr-home-store" :disabled="loading||!stores.length" :range="stores" range-key="name" :value="storeIndex" @change="chooseStore"><view><UiIcon name="pin" :size="26"/><text>{{shortStore(activeStore)}}</text><UiIcon name="chevron" :size="22"/></view></picker>
        <swiper v-if="homeBanners.length" class="xr-home-room xr-home-banner" circular autoplay :indicator-dots="homeBanners.length>1"><swiper-item v-for="banner in homeBanners" :key="banner.id" @click="homeModuleClick(banner)"><image :src="banner.image" mode="aspectFill"/><view class="xr-banner-caption"><text>{{banner.title}}</text><text>{{banner.subtitle}}</text></view></swiper-item></swiper><image v-else class="xr-home-room" :src="ui.room" mode="aspectFill"/>
        <view class="xr-home-headline">{{config.homeTitle||'美好，从照顾自己开始'}}</view><view class="xr-home-tagline">{{config.homeSubtitle||'科技美肤 · 私享护理'}}</view>
      </view>
      <view class="xr-quick-grid">
        <button v-for="entry in quickEntries" :key="entry.page+(entry.query||'')" class="xr-quick" @click="open(entry.page,entry.query||'')"><view class="xr-quick-circle"><UiIcon :name="entry.icon" tone="light" :size="44"/></view><text>{{entry.label}}</text></button>
      </view>
      <view class="xr-home-entry-grid xr-gutter">
        <button class="xr-home-entry xr-home-booking" @click="open('appointments')"><image :src="ui.booking" mode="aspectFill"/><view><text class="xr-editorial">{{config.bookingTitle||'在线预约'}}</text><text class="xr-tiny">{{config.bookingSubtitle||'专业护理 · 按需安排'}}</text><view class="xr-arrow-disc"><UiIcon name="arrow" tone="light" :size="26"/></view></view></button>
        <button class="xr-home-entry xr-home-vip" @click="openVip"><view><text class="xr-editorial">{{config.vipTitle||'VIP通道'}}</text><text class="xr-tiny">{{config.vipSubtitle||'专属服务 · 按次预约'}}</text></view><UiIcon name="crown" tone="rose" :size="66"/></button>
        <button class="xr-home-entry xr-home-stores" @click="open('stores')"><view><text class="xr-editorial">{{config.storesTitle||'查看门店'}}</text><text class="xr-tiny">{{config.storesSubtitle||'多店选择 · 就近服务'}}</text></view><UiIcon name="store" tone="rose" :size="62"/></button>
      </view>
      <button class="xr-home-alliance xr-gutter" @click="open('alliances')"><image :src="ui.alliance" mode="aspectFill"/><view><text class="xr-editorial">{{config.allianceTitle||'百业联盟'}}</text><text class="xr-tiny">{{config.allianceSubtitle||'发现生活里的更多美好'}}</text></view><UiIcon name="arrow" :size="34"/></button>
      <view class="xr-section-heading xr-gutter"><text>{{config.featuredTitle||'特色项目'}}</text><button class="xr-text-button" @click="switchTab('mall')">查看全部 <UiIcon name="chevron" :size="24"/></button></view>
      <view class="xr-featured-grid xr-gutter"><button v-for="product in homeFeatured" :key="product.id" class="xr-featured-card" @click="productPage(product)"><ProductVisual :product="product"/><view class="xr-featured-copy"><text class="xr-product-name">{{product.name}}</text><text class="xr-price">¥{{price(product.price)}}<text v-if="product.skus?.length" class="xr-tiny"> 起</text></text></view></button></view>
      <template v-if="goodsProducts.length"><view class="xr-section-heading xr-gutter"><text>{{config.goodsTitle||'优选单品'}}</text><button class="xr-text-button" @click="open('mall','?category='+goodsCategoryId)">查看全部 <UiIcon name="chevron" :size="24"/></button></view><view class="xr-featured-grid xr-gutter"><button v-for="product in goodsProducts" :key="product.id" class="xr-featured-card" @click="productPage(product)"><ProductVisual :product="product"/><view class="xr-featured-copy"><text class="xr-product-name">{{product.name}}</text><text class="xr-price">¥{{price(product.price)}}</text></view></button></view></template>
      <view v-if="homeContentModules.length" class="xr-home-modules xr-gutter"><button v-for="module in homeContentModules" :key="module.id" class="xr-module-card" @click="homeModuleClick(module)"><image v-if="module.image" :src="module.image" mode="aspectFill"/><view><text class="xr-product-name">{{module.title}}</text><text class="xr-caption">{{module.subtitle||module.description}}</text></view><UiIcon name="chevron" :size="28"/></button></view>
      <view class="xr-brand-footer"><BrandMark :name="brandName" :logo="config.brandLogo" :subtitle="config.brandTagline" compact/><text>用心照顾，每一份美好</text></view>
    </template>

    <template v-else-if="page==='mall'">
      <scroll-view class="xr-category-scroll" scroll-x><view class="xr-category-tabs"><button v-for="category in mallCategories" :key="category.id" :class="['xr-category-tab',{'is-active':mallCategory===category.id}]" @click="mallCategory=category.id">{{category.name}}</button></view></scroll-view>
      <view :class="['xr-banner','xr-mall-banner',{'xr-membership-banner':isVipCategory}]" :style="{backgroundImage:'url('+ui.portrait+')'}"><text class="xr-eyebrow">XIURONG</text><text class="xr-editorial">{{isVipCategory?'按需选择 · 分次预约':selectedMallCategoryName.includes('优选')?'日常呵护 · 用心甄选':'科技抗衰 · 按需选择'}}</text><text class="xr-caption">{{isVipCategory?'多档服务套餐，内容清晰可查':'专业美容仪器 · 定制护理方案'}}</text></view>
      <view class="xr-catalogue xr-gutter"><button v-for="(product,index) in mallProducts" :key="product.id" :class="['xr-catalogue-row',{'xr-vip-tier':isVipCategory}]" @click="productPage(product)"><view v-if="isVipCategory" :class="['xr-tier-symbol','xr-tier-'+index]"><UiIcon name="crown" tone="rose" :size="64"/></view><ProductVisual v-else :product="product"/><view class="xr-catalogue-copy"><text class="xr-product-name">{{product.name}}</text><text class="xr-caption">{{product.subtitle || (product.kind==='goods'?'日常护肤 · 优选单品':'到店服务 · 按需预约')}}</text><text class="xr-price">¥{{price(product.memberPrice??product.price)}}<text v-if="product.skus?.length" class="xr-tiny"> 起</text></text></view><text v-if="!isVipCategory" class="xr-small-cta">查看</text><UiIcon v-else name="chevron" :size="28"/></button></view>
      <EmptyState v-if="!loading&&!mallProducts.length" icon="bag" title="商品正在准备中" description="上架后将在这里展示" compact/>
      <view v-if="isVipCategory" class="xr-process xr-gutter"><view><UiIcon name="document"/><text>选方案</text></view><UiIcon name="arrow" tone="muted" :size="26"/><view><UiIcon name="store"/><text>{{onlinePay?'微信支付':'门店确认收款'}}</text></view><UiIcon name="arrow" tone="muted" :size="26"/><view><UiIcon name="calendar"/><text>按项目预约</text></view></view>
    </template>

    <template v-else-if="page==='product'&&product">
      <view v-if="isPackage" class="xr-package-hero" :style="{backgroundImage:'url('+ui.silk+')'}"><view><text class="xr-eyebrow">XIURONG · 秀荣礼遇</text><text class="xr-editorial">{{product.name}}</text><text class="xr-caption">按需选择 · 分次预约</text><text class="xr-price xr-price-large">¥{{price(unitPrice)}}</text></view><ProductVisual :product="packageHeroProduct"/></view>
      <view v-else-if="product.kind==='service'" class="xr-product-hero" :style="{backgroundImage:'url('+ui.silk+')'}"><ProductVisual :product="selectedVisualProduct"/><view class="xr-product-hero-copy"><text class="xr-editorial">{{product.name}}</text><text class="xr-caption">科技护理 · 到店服务</text><text v-if="product.subtitle" class="xr-soft-label">{{product.subtitle}}</text><text class="xr-price xr-price-large">{{product.trialOnly?'价值 ':''}}¥{{price(product.trialOnly?product.referencePrice:unitPrice)}}</text></view></view>
      <view v-else class="xr-goods-cover"><ProductVisual :product="selectedVisualProduct"/></view>
      <view v-if="product.kind==='goods'" class="xr-product-intro xr-gutter"><text class="xr-editorial">{{product.name}}</text><text v-if="product.subtitle" class="xr-caption">{{product.subtitle}}</text><text class="xr-price xr-price-large">¥{{price(unitPrice)}}</text></view>
      <PackagePicker v-if="isPackage" v-model="packageSelection" :plans="product.packagePlans" :disabled="busy||loading||!!error"/>
      <view v-else class="xr-panel xr-gutter">
        <button v-if="!product.trialOnly" class="xr-detail-row" @click="sheet=true"><UiIcon name="bag" :size="32"/><text>已选</text><text class="xr-row-value">{{selectedSku?.name||(spec==='course'?'疗程':product.kind==='goods'?'1件':'单次 · 1次')}}</text><UiIcon name="chevron" :size="24"/></button>
        <button v-if="product.kind==='service'" class="xr-detail-row" @click="open('stores')"><UiIcon name="pin" :size="32"/><text>适用门店</text><text class="xr-row-value xr-muted">查看门店</text><UiIcon name="chevron" :size="24"/></button>
        <view v-else class="xr-detail-row"><UiIcon name="truck" :size="32"/><text>配送方式</text><text class="xr-row-value">快递配送</text></view>
      </view>
      <view v-if="product.trialOnly" class="xr-notice xr-gutter"><UiIcon name="gift" tone="rose"/><text>领取{{product.gift&&!product.trial?'贵宾卡':'体验卡'}}后，可免费预约到店使用。</text></view>
      <view v-else-if="product.kind==='service'" class="xr-service-steps xr-gutter"><view><text class="xr-step-number">1</text><view><text>{{onlinePay?'付款成功后可预约':'门店确认收款后可预约'}}</text><text class="xr-caption">联系服务门店，确认到店时间</text></view></view><view><text class="xr-step-number">2</text><view><text>每次服务单独核销</text><text class="xr-caption">按服务次数预约，用心安排每次护理</text></view></view></view>
      <view class="xr-panel xr-gutter"><view class="xr-section-heading"><text>{{product.kind==='goods'?'商品详情':'项目介绍'}}</text></view><view class="xr-prose">{{product.description||'具体服务内容请联系门店了解。'}}</view><view v-if="product.brand" class="xr-caption xr-space-top">品牌：{{product.brand}}</view><view class="xr-stock"><text>已售 {{product.sold||0}}</text><text>{{availableStock>0?'库存 '+availableStock:'暂时售罄'}}</text></view></view>
      <image v-if="product.detailImage" class="xr-product-detail-image xr-gutter" :src="product.detailImage" mode="widthFix" @click="previewStore({gallery:[product.detailImage]},0)"/>
      <scroll-view v-if="product.gallery?.length" scroll-x class="xr-gallery xr-gutter"><view class="xr-gallery-track"><image v-for="(image,index) in product.gallery" :key="image" :src="image" mode="aspectFill" @click="previewStore({gallery:product.gallery},index)"/></view></scroll-view>
      <view class="xr-dock xr-product-dock"><button class="xr-mini-action" open-type="contact" @click="!nativeDevice&&contact()"><UiIcon name="headset" :size="38"/><text>客服</text></button><button v-if="config.marketingEnabled!==false" class="xr-mini-action" open-type="share" @click="!nativeDevice&&open('share')"><UiIcon name="share" :size="38"/><text>分享</text></button><button v-if="product.trialOnly" class="xr-button xr-button-primary" :disabled="busy||loading||!!error" @click="open('gifts',product.gift&&!product.trial?'?type=vip':'?type=trial')">领取卡券并预约</button><button v-else class="xr-button xr-button-primary" :disabled="!canBuy" @click="isPackage?checkoutPackage():sheet=true">{{availableStock<=0?'暂时售罄':isPackage?'确认方案':'选择规格'}}</button></view>
    </template>

    <template v-else-if="page==='stores'">
      <template v-if="displayStore">
        <view v-if="storePhoto(displayStore)" class="xr-store-cover"><image :src="storePhoto(displayStore)" mode="aspectFill" @click="previewStoreCover(displayStore)"/><text v-if="displayStore.gallery?.length" class="xr-photo-counter">{{displayStore.gallery.length}}张门店照片</text><text v-else-if="displayStore.imageCaption" class="xr-image-caption">{{displayStore.imageCaption}}</text></view>
        <view class="xr-store-intro xr-gutter"><text class="xr-editorial">{{storeName(displayStore)}}</text><text class="xr-soft-label">科技美肤 · 到店护理</text></view>
        <view class="xr-panel xr-gutter"><button class="xr-info-line" @click="copyStoreAddress(displayStore)"><UiIcon name="pin" :size="34"/><text>{{displayStore.address||'门店地址待补充'}}</text><text class="xr-tiny xr-nowrap">复制地址</text></button><button v-if="displayStore.phone" class="xr-info-line" @click="call(displayStore.phone)"><UiIcon name="phone" :size="34"/><text class="xr-price">{{displayStore.phone}}</text></button></view>
        <view v-if="displayStore.gallery?.length" class="xr-panel xr-gutter"><view class="xr-section-heading"><text>门店环境</text><text class="xr-caption">点击查看大图</text></view><scroll-view scroll-x class="xr-gallery"><view class="xr-gallery-track"><image v-for="(image,index) in displayStore.gallery" :key="image" :src="image" mode="aspectFill" @click="previewStore(displayStore,index)"/></view></scroll-view></view>
        <view class="xr-notice xr-gutter"><UiIcon name="info" tone="rose" :size="30"/><text>{{displayStore.hours?'营业时间：'+displayStore.hours:'具体营业时间请联系门店'}}</text></view>
        <view class="xr-dock"><button class="xr-button xr-button-outline" @click="contact(displayStore)"><UiIcon name="phone" :size="34"/>联系门店</button><button class="xr-button xr-button-primary" @click="chooseStoreBooking(displayStore)">选择服务预约</button></view>
      </template>
      <template v-else>
        <view class="xr-page-intro xr-gutter"><text class="xr-editorial">找到你的美肤空间</text><text class="xr-caption">专业科技美肤 · 舒适私享体验</text></view>
        <view v-for="store in stores" :key="store.id" class="xr-store-card xr-gutter"><button class="xr-store-photo" @click="viewStore(store)"><image v-if="storePhoto(store)" :src="storePhoto(store)" mode="aspectFill"/><BrandMark :name="brandName" :logo="config.brandLogo" :subtitle="config.brandTagline" v-else compact/><text v-if="store.imageCaption&&!store.gallery?.length" class="xr-image-caption">{{store.imageCaption}}</text></button><view class="xr-store-card-copy"><text class="xr-editorial">{{storeName(store)}}</text><view class="xr-info-line"><UiIcon name="pin" :size="30"/><text>{{store.address||'门店地址待补充'}}</text></view><button v-if="store.phone" class="xr-info-line" @click="call(store.phone)"><UiIcon name="phone" :size="30"/><text class="xr-price">{{store.phone}}</text></button><button class="xr-button xr-button-primary xr-button-small" @click="viewStore(store)">查看门店</button></view></view>
        <EmptyState v-if="!loading&&!stores.length" icon="store" title="暂无可展示门店" description="门店上架后将在这里展示"/>
        <view class="xr-footnote"><UiIcon name="info" :size="26"/>预约前请确认服务门店</view>
      </template>
    </template>

    <template v-else-if="page==='gifts'">
      <view v-if="hasGiftClaim" class="xr-tabs xr-gutter"><button :class="{'is-active':giftType==='trial'}" @click="giftType!=='trial'&&showGiftType('trial')">体验卡</button><button :class="{'is-active':giftType==='vip'}" @click="giftType!=='vip'&&showGiftType('vip')">贵宾卡</button></view>
      <view v-else class="xr-gift-hero" :style="{backgroundImage:'url('+ui.silk+')'}"><BrandMark :name="brandName" :logo="config.brandLogo" :subtitle="config.brandTagline" compact/><text class="xr-editorial">{{giftType==='trial'?'三项体验 · 免费领取':'科技抗衰 · 十选三'}}</text><text class="xr-caption">{{giftType==='trial'?'每位会员限领一次':'受邀会员专享 · 免费领取'}}</text></view>
      <template v-if="!hasGiftClaim&&!giftEligible">
        <EmptyState icon="lock" title="暂未获得领取资格" description="贵宾卡面向受邀会员开放，可联系门店了解领取资格。"/>
        <view class="xr-gutter xr-stack"><button class="xr-button" disabled>暂不可领取</button><button class="xr-button xr-button-primary" @click="contact()">联系门店</button><button class="xr-text-button" @click="showGiftType('trial')">先领取体验卡 <UiIcon name="arrow" :size="30"/></button></view>
      </template>
      <template v-else-if="!hasGiftClaim">
        <view v-if="giftType==='vip'" class="xr-vip-picks xr-panel xr-gutter"><view class="xr-list-heading"><text>项目列表</text><text>项目价值</text></view><button v-for="(product,index) in giftProducts" :key="product.id" :class="['xr-vip-pick',{'is-selected':selectedGifts.includes(product.id)}]" :disabled="busy||loading||!!error" @click="selectGift(product.id)"><text :class="['xr-check',{'is-checked':selectedGifts.includes(product.id)}]">{{selectedGifts.includes(product.id)?'✓':''}}</text><text class="xr-pick-number">{{index+1<10?'0':''}}{{index+1}}</text><text class="xr-pick-name">{{giftLabel(product)}}</text><text class="xr-price">¥{{price(product.referencePrice??product.price)}}</text></button></view>
        <view v-else class="xr-trial-list xr-gutter"><button v-for="product in giftProducts" :key="product.id" :class="['xr-trial-card',{'is-selected':selectedGifts.includes(product.id)}]" :disabled="busy||loading||!!error" @click="selectGift(product.id)"><text :class="['xr-check',{'is-checked':selectedGifts.includes(product.id)}]">{{selectedGifts.includes(product.id)?'✓':''}}</text><ProductVisual :product="product"/><view><text class="xr-product-name">{{product.name}}</text><text class="xr-caption">{{product.subtitle||'到店服务'}} · 1次</text><text class="xr-value-strip">价值 <text>¥{{price(product.referencePrice??product.price)}}</text></text></view></button></view>
        <EmptyState v-if="!loading&&!giftProducts.length" icon="ticket" title="体验项目正在准备中" description="项目上架后，可在这里选择领取" compact/>
        <view v-if="giftProducts.length<maxGiftCount&&giftProducts.length" class="xr-notice xr-gutter"><UiIcon name="info" tone="rose" :size="30"/><text>当前可选{{giftProducts.length}}项，满{{maxGiftCount}}项后可领取，请联系门店。</text></view>
        <view class="xr-notice xr-gutter"><UiIcon name="gift" tone="rose" :size="32"/><text>领取免费，无需购买。每个项目领取后单独预约。</text></view>
        <view class="xr-dock"><view class="xr-dock-summary">已选 <text>{{selectedGifts.length}}/{{maxGiftCount}}</text></view><button class="xr-button xr-button-primary" :disabled="!canClaim" @click="claim">{{busy?'领取中…':'确认免费领取'}}</button></view>
      </template>
      <template v-else>
        <view class="xr-claim-summary xr-gutter"><UiIcon :name="claimedJustNow?'check-circle':'calendar'" tone="rose" :size="48"/><view><text>{{claimedJustNow?'领取成功':'已领'+receivedGifts.length+'项'}} · 可预约{{availableClaimGifts.length}}项</text><text class="xr-caption">领取后，每个项目单独预约使用</text></view></view>
        <view v-for="product in receivedGifts" :key="product.claimId+'-'+product.id" class="xr-claimed-card xr-gutter"><ProductVisual :product="product"/><view class="xr-claimed-copy"><text class="xr-product-name">{{product.name}}</text><text class="xr-caption">{{product.subtitle||'到店服务'}} · 1次</text><text :class="['xr-badge','xr-badge-'+giftStatusClass(product)]">{{giftStatus(product)}}</text><button v-if="product.kind==='service'&&product.useStatus==='available'" class="xr-button xr-button-primary xr-button-small" :disabled="busy||loading||!!error" @click="startGiftBooking(product)">预约使用</button><button v-else-if="product.useStatus==='booked'" class="xr-button xr-button-outline xr-button-small" @click="open('appointments','?tab=booked')">查看预约</button><button v-else class="xr-button xr-button-outline xr-button-small" @click="product.kind==='service'?open('appointments','?tab=completed'):productPage(product)">{{product.kind==='service'?'查看记录':'查看详情'}}</button></view></view>
        <view class="xr-gutter xr-stack xr-space-top"><button class="xr-button xr-button-outline" @click="open('appointments')">查看全部预约</button><button class="xr-text-button" @click="showGiftType(giftType==='trial'?'vip':'trial')">查看{{giftType==='trial'?'贵宾卡':'体验卡'}} <UiIcon name="arrow" :size="28"/></button></view>
      </template>
    </template>

    <template v-else-if="page==='login'">
