    <template v-else-if="page==='profile'">
      <view class="xr-profile-editor"><image class="xr-profile-backdrop" :src="ui.room" mode="aspectFill"/><view class="xr-avatar-editor"><image v-if="hasCustomAvatar(form.avatar||me.avatar)" :src="form.avatar||me.avatar" mode="aspectFill" @click="chooseAvatar"/><view v-else class="xr-avatar-placeholder" @click="chooseAvatar"><UiIcon name="user" tone="rose" :size="80"/></view><button class="xr-soft-label" :disabled="busy||loading" @click="chooseAvatar">更换头像</button><button class="xr-text-button xr-tiny" :disabled="busy||loading" @click="removeAvatar">移除</button></view></view>
      <view class="xr-form xr-gutter"><view class="xr-form-field"><label><text class="xr-required">*</text>姓名</label><input v-model="form.name" :disabled="loading||busy" placeholder="请输入姓名" maxlength="40" aria-label="姓名"/></view><view class="xr-form-field"><label><text class="xr-required">*</text>性别</label><view class="xr-gender"><button :class="{'is-selected':form.gender==='male'}" :disabled="busy||loading" @click="form.gender='male'"><text :class="['xr-check',{'is-checked':form.gender==='male'}]">{{form.gender==='male'?'✓':''}}</text>先生</button><button :class="{'is-selected':form.gender==='female'}" :disabled="busy||loading" @click="form.gender='female'"><text :class="['xr-check',{'is-checked':form.gender==='female'}]">{{form.gender==='female'?'✓':''}}</text>女士</button></view></view><view class="xr-footnote">完善资料，方便门店为你安排服务</view><button class="xr-button xr-button-primary" :disabled="!profileValid||busy||loading||!!error" @click="saveProfile">{{busy?'保存中…':'保存信息'}}</button></view>
    </template>

    <template v-else-if="page==='mine'">
      <view class="xr-member-head" :style="{backgroundImage:'url('+ui.silk+')'}"><button class="xr-profile-row" @click="open(me.id?'profile':'login')"><image v-if="hasCustomAvatar(me.avatar)" :src="me.avatar" mode="aspectFill"/><view v-else class="xr-avatar-placeholder"><UiIcon name="user" tone="rose" :size="66"/></view><view><text class="xr-product-name">{{me.id?(me.name||'微信会员'):'点击登录'}}</text><text class="xr-caption">{{me.id?'欢迎来到'+brandName:'登录后领取卡券、预约到店服务'}}</text></view><text class="xr-tiny">{{me.id?'编辑资料':'去登录'}}</text><UiIcon name="chevron" :size="24"/></button><view class="xr-member-card"><button class="xr-membership-heading" @click="openVip"><UiIcon name="crown" tone="rose" :size="64"/><view><text class="xr-editorial">{{me.id?'秀荣会员':'欢迎加入秀荣'}}</text><text class="xr-caption">专注科技美肤 · 私享护理</text></view><UiIcon name="chevron" :size="26"/></button><view class="xr-member-stats"><button @click="open('points')"><text class="xr-caption">我的积分</text><text class="xr-stat-value">{{me.id?(me.points||0):'—'}}</text></button><button @click="open('earnings')"><text class="xr-caption">我的收益</text><text class="xr-stat-value">{{me.id?'¥'+price(incomeSummary.total??earningsTotal,true):'—'}}</text></button></view></view></view>
      <view class="xr-panel xr-gutter"><view class="xr-section-heading"><text>我的订单</text><button class="xr-text-button" @click="open('orders')">查看全部 <UiIcon name="chevron" :size="24"/></button></view><view class="xr-order-shortcuts"><button @click="open('orders','?tab=pending')"><UiIcon name="bag" :size="48"/><text>待付款</text></button><button @click="open('appointments')"><UiIcon name="calendar" :size="48"/><text>待预约</text></button><button @click="open('orders','?tab=completed')"><UiIcon name="receipt" :size="48"/><text>已完成</text></button></view></view>
      <view class="xr-member-grid xr-gutter"><button v-for="entry in memberEntries" :key="entry.page" @click="open(entry.page,entry.query||'')"><UiIcon :name="entry.icon" tone="rose" :size="46"/><text>{{entry.label}}</text></button></view>
      <view v-if="poolOpen" class="xr-pool-entry xr-gutter"><button @click="open('earnings')"><UiIcon name="crown" tone="rose" :size="42"/><view><text>VIP分红池</text><text class="xr-caption">{{poolNote}}</text></view><UiIcon name="chevron" :size="26"/></button></view>
      <view class="xr-menu xr-panel xr-gutter"><button class="xr-menu-row" @click="open('addresses')"><UiIcon name="pin" :size="36"/><text>收货地址</text><UiIcon name="chevron" :size="26"/></button><button class="xr-menu-row" open-type="contact" session-from="mine" @click="!nativeDevice&&contact()"><UiIcon name="headset" :size="36"/><text>在线客服</text><UiIcon name="chevron" :size="26"/></button><button class="xr-menu-row" @click="open('about')"><UiIcon name="info" :size="36"/><text>关于我们</text><UiIcon name="chevron" :size="26"/></button></view>
      <button v-if="me.id" class="xr-text-button xr-logout" :disabled="busy" @click="logout"><UiIcon name="logout" tone="muted" :size="30"/>退出登录</button>
    </template>

    <template v-else-if="page==='addresses'">
      <view v-for="address in rows" :key="address.id" class="xr-address-card xr-panel xr-gutter"><view class="xr-address-top"><UiIcon name="pin" tone="rose" :size="40"/><text v-if="address.isDefault" class="xr-badge xr-badge-rose">默认地址</text></view><text class="xr-product-name">{{address.name}}　{{address.phone}}</text><text class="xr-address-detail">{{address.city}} {{address.detail}}</text><view class="xr-address-actions"><button @click="open('address-edit','?id='+address.id)">编辑</button><button :disabled="busy" @click="deleteAddress(address)">删除</button></view></view>
      <EmptyState v-if="!loading&&!rows.length" icon="pin" title="还没有收货地址" description="添加地址，方便配送实物商品"/>
      <view class="xr-footnote">默认地址用于实物商品配送，一个账号可添加多个收货地址。</view><view class="xr-dock"><button class="xr-button xr-button-primary" @click="open('address-edit')"><UiIcon name="plus" tone="light" :size="32"/>添加地址</button></view>
    </template>

    <template v-else-if="page==='address-edit'">
      <view class="xr-form xr-panel xr-gutter"><view class="xr-form-field"><label><text class="xr-required">*</text>姓名</label><input v-model="form.name" :disabled="loading||busy" placeholder="请输入收货人姓名" maxlength="40" aria-label="收货人姓名"/></view><view class="xr-form-field"><label><text class="xr-required">*</text>手机号码</label><input v-model="form.phone" :disabled="loading||busy" placeholder="请输入11位手机号码" type="number" maxlength="11" aria-label="手机号码"/></view><view class="xr-form-field"><label><text class="xr-required">*</text>所在地区</label>
      <!-- #ifdef MP-WEIXIN -->
      <picker mode="region" :value="regionValue" :disabled="loading||busy" @change="form.city=$event.detail.value.join(' ')"><view :class="['xr-picker-field',{'xr-placeholder':!form.city}]"><text>{{form.city||'请选择省市区'}}</text><UiIcon name="chevron" :size="26"/></view></picker>
      <!-- #endif -->
      <!-- #ifdef H5 -->
      <input v-model="form.city" :disabled="loading||busy" placeholder="请输入省、市、区" aria-label="所在地区"/>
      <!-- #endif -->
      </view><view class="xr-form-field"><label><text class="xr-required">*</text>详细地址</label><textarea v-model="form.detail" class="xr-address-textarea" :disabled="loading||busy" placeholder="请输入街道门牌等信息" maxlength="200" aria-label="详细地址"/></view><view class="xr-switch-row"><text>设为默认</text><switch :checked="!!form.isDefault" :disabled="loading||busy" color="#bc817b" @change="form.isDefault=$event.detail.value"/></view><view class="xr-footnote">请填写完整收货信息</view><button class="xr-button xr-button-primary" :disabled="!addressValid||busy||loading||!!error" @click="saveAddress">{{busy?'保存中…':'保存地址'}}</button></view>
    </template>

    <template v-else-if="['product','checkout'].includes(page)&&!product"><EmptyState v-if="!loading" icon="bag" :title="error?'暂时无法加载商品':'商品不存在或已下架'" :description="error?'请检查网络后重试':'可以到商城看看其他项目'" :action="error?'重新加载':'返回商城'" @action="error?refresh():switchTab('mall')"/></template>

    <template v-else-if="page==='checkout'&&product">
      <view v-if="product.kind==='goods'" class="xr-panel xr-gutter"><view class="xr-section-heading"><text>收货信息</text><button class="xr-text-button" @click="open('addresses')">管理地址 <UiIcon name="chevron" :size="24"/></button></view><picker v-if="addresses.length" :disabled="loading||busy" :range="addresses" range-key="detail" :value="addressIndex" @change="addressIndex=Number($event.detail.value)"><view class="xr-info-line"><UiIcon name="pin" tone="rose" :size="40"/><view><text class="xr-product-name">{{chosenAddress.name}} {{chosenAddress.phone}}</text><text class="xr-caption">{{chosenAddress.city}} {{chosenAddress.detail}}</text></view><UiIcon name="chevron" :size="26"/></view></picker><button v-else class="xr-menu-row" @click="open('address-edit')"><UiIcon name="plus" :size="34"/><text>添加收货地址</text><UiIcon name="chevron" :size="26"/></button></view>
      <view class="xr-order-product xr-panel xr-gutter"><ProductVisual :product="product"/><view class="xr-order-product-copy"><text class="xr-product-name">{{product.name}}</text><text class="xr-caption">{{selectedPackagePlan?.name||selectedSku?.name||(spec==='course'?'1疗程':product.kind==='goods'?'1件':'单次 · 1次')}}</text><view class="xr-between"><text class="xr-price">¥{{price(unitPrice)}}</text><text>×{{quantity}}</text></view></view></view>
      <PackagePicker v-if="isPackage" v-model="packageSelection" :plans="product.packagePlans" :disabled="busy||loading||!!error"/>
      <view class="xr-panel xr-gutter"><picker :disabled="loading||busy||!stores.length" :range="stores" range-key="name" :value="storeIndex" @change="chooseStore"><view class="xr-detail-row"><UiIcon name="store" :size="36"/><text>{{product.kind==='goods'?'服务门店':'服务门店'}}</text><text class="xr-row-value">{{shortStore(chosenStore)}}</text><UiIcon name="chevron" :size="26"/></view></picker><view class="xr-caption xr-space-top">{{chosenStore.address||'请选择有效门店'}}</view></view>
      <view class="xr-panel xr-gutter"><view class="xr-section-heading"><text>订单金额</text></view><view class="xr-key-value"><text>商品金额</text><text>¥{{price(total)}}</text></view><view class="xr-key-value"><text>数量</text><text>{{quantity}}</text></view><view class="xr-key-value xr-total-line"><text>合计</text><text class="xr-price">¥{{price(total)}}</text></view></view>
      <view class="xr-panel xr-gutter"><view class="xr-detail-row"><UiIcon :name="product.kind==='goods'?'truck':'store'" :size="34"/><text>{{product.kind==='goods'?'配送方式':'服务方式'}}</text><text class="xr-row-value">{{product.kind==='goods'?'快递配送':'到店服务'}}</text></view><view v-if="product.kind==='service'" class="xr-detail-row"><UiIcon name="clock" :size="34"/><text>预约说明</text><text class="xr-row-value">{{onlinePay?'付款成功后可预约':'门店确认收款后可预约'}}</text></view><view class="xr-detail-row"><UiIcon name="bag" :size="34"/><text>支付方式</text><text class="xr-row-value">{{onlinePay?'微信支付':'联系门店确认付款'}}</text></view></view>
      <view v-if="purchaseIncomeRule" class="xr-panel xr-gutter"><view class="xr-section-heading"><text>套餐收益规则</text></view><view class="xr-prose xr-caption">{{purchaseIncomeText}}</view></view>
      <view class="xr-panel xr-gutter"><view class="xr-section-heading"><text>备注 <text class="xr-caption">（选填）</text></text></view><input v-model="form.message" :disabled="busy" placeholder="如有其他需求，请填写备注信息" maxlength="200" class="xr-remark-input"/></view>
      <view class="xr-notice xr-gutter"><UiIcon name="info" tone="rose" :size="32"/><text>{{onlinePay?'提交后将调起微信支付，请在2小时内完成支付，超时未付款订单自动取消。':'提交后请在2小时内联系门店确认付款，超时未付款订单自动取消。'}}</text></view>
      <view class="xr-dock"><view class="xr-dock-summary">合计 <text class="xr-price">¥{{price(total)}}</text></view><button class="xr-button xr-button-primary" :disabled="!checkoutReady" @click="createOrder">{{busy?'提交中…':onlinePay?'提交并支付':'提交订单'}}</button></view>
    </template>

    <template v-else-if="page==='orders'">
      <scroll-view class="xr-tabs-scroll" scroll-x><view class="xr-tabs"><button v-for="(label,index) in orderTabs" :key="label" :class="{'is-active':tab===index}" @click="tab=index">{{label}}</button></view></scroll-view>
      <view v-for="orderRow in filteredRows" :key="orderRow.id" class="xr-order-card xr-panel xr-gutter"><view class="xr-between"><text class="xr-tiny xr-muted">{{shortDate(orderRow.createdAt)}}</text><text :class="['xr-badge',orderRow.status==='pending'?'xr-badge-rose':'xr-badge-muted']">{{orderStatus(orderRow)}}</text></view><button class="xr-order-product" @click="open('order-detail','?id='+orderRow.id)"><ProductVisual :product="orderRow.product||{}"/><view class="xr-order-product-copy"><text class="xr-product-name">{{orderRow.product?.name}}</text><text class="xr-caption">{{orderSpec(orderRow)}} · {{orderRow.quantity}}件</text><text class="xr-price">¥{{price(orderRow.total)}}</text></view></button><view class="xr-order-actions"><button v-if="orderRow.status==='pending'" class="xr-button xr-button-outline xr-button-small" :disabled="busy" @click="cancelOrder(orderRow)">取消订单</button><button class="xr-button xr-button-outline xr-button-small" @click="open('order-detail','?id='+orderRow.id)">查看详情</button><button v-if="orderRow.status==='pending'" class="xr-button xr-button-primary xr-button-small" @click="pay(orderRow)">{{onlinePay?'立即支付':'联系门店'}}</button><button v-if="orderRow.status==='ready'&&orderRow.product?.kind==='service'" class="xr-button xr-button-primary xr-button-small" @click="open('order-detail','?id='+orderRow.id)">预约服务</button></view></view>
      <EmptyState v-if="!loading&&!filteredRows.length" icon="receipt" title="还没有相关订单" description="选一项喜欢的护理，开始美好体验" action="去商城看看" @action="switchTab('mall')"/>
    </template>

    <template v-else-if="page==='order-detail'&&order">
      <view :class="['xr-order-status','xr-status-'+order.status]" :style="{backgroundImage:'url('+ui.silk+')'}"><UiIcon :name="order.status==='shipping'?'truck':order.status==='completed'?'check-circle':order.status==='cancelled'?'close':order.status==='aftersale'?'receipt':'clock'" tone="rose" :size="64"/><view><text class="xr-editorial">{{orderStatus(order)}}</text><text class="xr-caption">{{orderNote(order)}}</text></view></view>
      <view class="xr-order-product xr-panel xr-gutter"><ProductVisual :product="order.product||{}"/><view class="xr-order-product-copy"><text class="xr-product-name">{{order.product?.name}}</text><text class="xr-caption">{{orderSpec(order)}} · {{order.quantity}}件</text><text class="xr-price">¥{{price(order.total)}}</text></view></view>
      <view v-if="order.package" class="xr-panel xr-gutter"><view class="xr-section-heading"><text>{{order.package.planId==='service-course'?'疗程权益':'套餐服务权益'}}</text></view><view class="xr-entitlement-total">总次数 <text>{{entitlementTotals.total}}</text> 次</view><view class="xr-entitlement-stats"><view><text>已使用</text><text>{{entitlementTotals.used}}<text>次</text></text></view><view><text>已预约</text><text>{{entitlementTotals.booked}}<text>次</text></text></view><view><text>可预约</text><text>{{order.status==='ready'?entitlementTotals.available:0}}<text>次</text></text></view></view><view v-for="service in orderServices" :key="service.id" class="xr-entitlement-row"><ProductVisual :product="service"/><view><text class="xr-product-name">{{service.name}}</text><text class="xr-caption">共{{service.total}}次 · 已用{{service.used}}次<text v-if="order.status==='ready'"> · 可约{{packageRemaining(order,service)}}次</text></text></view><button v-if="order.status==='ready'&&packageRemaining(order,service)>0" class="xr-button xr-button-primary xr-button-small" :disabled="busy||!!error" @click="openPackageBooking(order,service)">预约</button><text v-else-if="service.used>=service.total" class="xr-badge xr-badge-muted">已用完</text></view><view v-if="order.status==='pending'" class="xr-caption xr-space-top">{{onlinePay?'付款成功后，可按项目分次预约。':'门店确认收款后，可按项目分次预约。'}}</view></view>
      <view v-if="orderAppointments.length" class="xr-panel xr-gutter"><view class="xr-section-heading"><text>服务记录</text></view><view v-for="record in orderAppointments" :key="record.id" class="xr-service-record"><view class="xr-record-dot"/><text>{{record.date}}　{{record.time}}</text><text class="xr-badge xr-badge-rose">{{record.status==='completed'?'已核销':record.status==='booked'?'已预约':'已取消'}}</text></view></view>
      <view v-if="order.address" class="xr-panel xr-gutter"><view class="xr-section-heading"><UiIcon name="pin" :size="34"/><text>收货信息</text></view><text class="xr-product-name">{{order.address.name}} {{order.address.phone}}</text><view class="xr-caption xr-space-top">{{order.address.city}} {{order.address.detail}}</view></view>
      <view v-if="order.tracking" class="xr-panel xr-gutter"><view class="xr-section-heading"><UiIcon name="truck" :size="34"/><text>物流 / 取货信息</text></view><view class="xr-prose">{{order.tracking}}</view></view>
      <view class="xr-panel xr-gutter"><view class="xr-section-heading"><text>服务门店</text></view><view class="xr-key-value"><text>门店</text><text>{{storeName(orderStore)||'原门店信息已变更'}}</text></view><view class="xr-info-line"><UiIcon name="pin" :size="30"/><text>{{orderStore.address||'请联系门店确认'}}</text></view><button v-if="orderStore.phone" class="xr-info-line" @click="call(orderStore.phone)"><UiIcon name="phone" :size="30"/><text class="xr-price">{{orderStore.phone}}</text></button></view>
      <view class="xr-panel xr-gutter"><view class="xr-section-heading"><text>订单信息</text></view><button class="xr-key-value" @click="copy(order.number)"><text>订单编号</text><text>{{order.number}} <UiIcon name="copy" tone="muted" :size="24"/></text></button><view class="xr-key-value"><text>下单时间</text><text>{{shortDate(order.createdAt)}}</text></view><view class="xr-key-value"><text>商品金额</text><text>¥{{price(order.total)}}</text></view><view class="xr-key-value"><text>付款状态</text><text>{{order.status==='pending'?(onlinePay?'待支付':'待门店确认'):order.status==='cancelled'?'已取消':order.status==='aftersale'?refundText(order):order.paymentMode==='wechat'?'微信支付成功':'已确认收款'}}</text></view><view v-if="order.refundNote" class="xr-notice"><UiIcon name="info" tone="rose" :size="30"/><text>{{order.refundNote}}</text></view></view>
      <view v-if="order.status==='aftersale'" class="xr-notice xr-gutter"><UiIcon name="info" tone="rose" :size="32"/><text>本页展示售后记录，具体到账情况请联系门店核实。</text></view>
      <view class="xr-dock"><button v-if="order.status==='pending'" class="xr-button xr-button-outline" :disabled="busy" @click="cancelOrder(order)">取消订单</button><button v-else class="xr-button xr-button-outline" @click="contact(orderStore)"><UiIcon name="phone" :size="32"/>联系门店</button><button v-if="order.status==='pending'" class="xr-button xr-button-primary" @click="pay(order)">{{onlinePay?'立即支付':'联系门店付款'}}</button><button v-else-if="order.status==='ready'&&order.product?.kind==='service'" class="xr-button xr-button-primary" @click="open('appointments')">预约服务</button><button v-else class="xr-button xr-button-primary" @click="open('orders')">返回订单</button></view>
    </template>
    <template v-else-if="page==='order-detail'"><EmptyState v-if="!loading" icon="receipt" :title="error?'暂时无法加载订单':'订单未找到'" :description="error?'请检查网络后重试':'可返回订单列表查看'" :action="error?'重新加载':'返回订单'" @action="error?refresh():open('orders')"/></template>

    <template v-else-if="page==='appointments'">
      <view class="xr-tabs xr-gutter"><button v-for="(label,index) in ['待预约','已预约','已完成']" :key="label" :class="{'is-active':tab===index}" @click="tab=index">{{label}}</button></view>
      <view v-for="record in filteredRows" :key="record.id" class="xr-appointment-card xr-panel xr-gutter">
        <view v-if="tab!==0" class="xr-between"><text class="xr-appointment-date">{{calendarLabel(record.date)}}</text><text class="xr-badge xr-badge-rose">{{tab===1?'已预约':'已完成'}}</text></view>
        <view class="xr-appointment-product"><view><text v-if="tab!==0" class="xr-appointment-time">{{record.time}}</text><text class="xr-product-name">{{appointmentName(record)}}</text><text v-if="tab===0" class="xr-caption">{{record.entitlementId?'可预约'+record.remaining+'次':'已购买服务，可选择时间预约'}}</text></view><ProductVisual :product="appointmentProduct(record)"/></view>
        <view class="xr-info-line"><UiIcon name="store" :size="32"/><text>{{storeName(recordStore(record))||'原门店信息已变更'}}</text></view><view v-if="recordStore(record).address" class="xr-caption xr-space-bottom">{{recordStore(record).address}}</view><view v-if="tab!==0" class="xr-info-line"><UiIcon name="clock" :size="32"/><text>服务时长{{record.durationMinutes||60}}分钟<text v-if="record.staff?.name"> · {{record.staff.name}}</text></text></view>
        <view class="xr-order-actions"><button v-if="tab===0" class="xr-button xr-button-primary xr-button-small" :disabled="busy||loading||!!error" @click="startOrderBooking(record)">立即预约</button><button v-if="record.orderId" class="xr-button xr-button-outline xr-button-small" @click="open('order-detail','?id='+record.orderId)">查看订单</button><button class="xr-button xr-button-outline xr-button-small" @click="contact(recordStore(record))">联系门店</button></view>
      </view>
      <template v-if="tab===0&&availableClaimGifts.length"><view class="xr-section-heading xr-gutter"><text>还有卡券服务待预约</text></view><view v-for="product in availableClaimGifts" :key="product.claimId+'-'+product.id" class="xr-available-gift xr-panel xr-gutter"><UiIcon name="ticket" tone="rose" :size="48"/><view><text class="xr-product-name">{{product.name}}</text><text class="xr-caption">{{product.claimType==='trial'?'体验卡':'贵宾卡'}} · 1次</text></view><button class="xr-button xr-button-primary xr-button-small" :disabled="busy||loading||!!error" @click="startGiftBooking(product)">去预约</button></view></template>
      <EmptyState v-if="!loading&&!filteredRows.length&&!(tab===0&&availableClaimGifts.length)" icon="calendar" :title="tab===0?'暂无待预约项目':tab===1?'暂无已预约记录':'暂无已完成记录'" :description="tab===0?'可以先领取体验卡，或购买喜欢的项目':'服务记录会在这里清晰展示'" :action="tab===0?'领取体验卡':''" @action="open('gifts','?type=trial')"/>
      <view class="xr-footnote"><UiIcon name="clock" :size="26"/>全部预约时间均为北京时间</view>
    </template>

    <template v-else-if="page==='booking'">
      <template v-if="bookingResult">
        <view class="xr-booking-success"><view class="xr-success-symbol"><UiIcon name="check" tone="rose" :size="84"/></view><text class="xr-editorial">预约成功</text><text class="xr-caption">期待与你在门店相见</text></view>
        <view class="xr-booking-ticket xr-gutter"><view class="xr-ticket-top"><view><text class="xr-appointment-date">{{bookedDateLabel}}</text><text class="xr-appointment-time">{{bookingResult.time}}</text></view><ProductVisual :product="bookingResult.product||{}"/></view><text class="xr-editorial">{{bookingResult.product?.name||'到店服务'}}</text><text class="xr-caption">本次预约使用1次 · {{bookingResult.durationMinutes}}分钟</text><view class="xr-ticket-divider"/><view class="xr-info-line"><UiIcon name="store" :size="34"/><text>{{storeName(bookingResultStore)}}</text></view><view class="xr-info-line"><UiIcon name="pin" :size="32"/><text>{{bookingResultStore.address}}</text></view><button v-if="bookingResultStore.phone" class="xr-info-line" @click="call(bookingResultStore.phone)"><UiIcon name="phone" :size="32"/><text class="xr-price">{{bookingResultStore.phone}}</text></button></view>
        <view class="xr-service-steps xr-gutter"><view><text class="xr-step-number">1</text><text>到店出示预约信息</text></view><view><text class="xr-step-number">2</text><text>服务完成后核销1次</text></view></view><view class="xr-footnote">如需调整，请联系服务门店。</view><view class="xr-gutter xr-stack"><button class="xr-button xr-button-primary" @click="open('appointments','?tab=booked')">查看我的预约</button><button class="xr-text-button" @click="switchTab('home')">返回首页</button></view>
      </template>
      <template v-else>
        <view v-if="bookingProduct" class="xr-order-product xr-panel xr-gutter"><ProductVisual :product="bookingProduct"/><view class="xr-order-product-copy"><text class="xr-product-name">{{bookingProduct.name}}</text><text class="xr-caption">{{query.claimId?(bookingClaim?.type==='vip'?'贵宾卡服务':'体验卡项目，无需支付'):order?.package?'疗程项目 · 本次使用1次':'已购买服务'}}</text></view></view>
        <view v-if="bookingProduct" class="xr-panel xr-gutter"><picker v-if="query.claimId" :disabled="loading||!bookingAvailable||!stores.length" :range="stores" range-key="name" :value="storeIndex" @change="chooseStore"><view class="xr-detail-row"><UiIcon name="store" :size="36"/><text>服务门店</text><text class="xr-row-value">{{shortStore(bookingStore)}}</text><UiIcon name="chevron" :size="26"/></view></picker><view v-else class="xr-detail-row"><UiIcon name="store" :size="36"/><text>服务门店</text><text class="xr-row-value">{{shortStore(bookingStore)}}</text></view><view class="xr-caption xr-space-top">{{bookingStore.address||'请联系门店确认地址'}}</view></view>
        <EmptyState v-if="!loading&&!bookingProduct" icon="calendar" :title="error?'暂时无法加载预约信息':'项目暂不可预约'" :description="error?'请检查网络后重试':'可以在我的预约中查看服务状态'" :action="error?'重新加载':'查看我的预约'" @action="error?refresh():open('appointments')"/>
        <view v-else-if="!loading&&!bookingAvailable" class="xr-notice xr-gutter"><UiIcon name="info" tone="rose"/><text>该项目已预约、已使用或暂不可预约，请在我的预约中查看使用状态。</text><button class="xr-text-button" @click="open('appointments')">查看记录</button></view>
        <view v-if="bookingProduct&&!bookingStoreEnabled&&!loading" class="xr-notice xr-gutter"><UiIcon name="info" tone="rose"/><text>原门店暂不可预约，请联系门店或选择营业中的门店。</text></view>
        <BookingAvailability v-if="bookingProduct" :source="bookingSource" :disabled="loading||!!error||!bookingAvailable||!bookingStoreEnabled" :today="today" :refresh-key="bookingRefresh" @selection="setBookingSelection"/>
        <view v-if="bookingProduct" class="xr-dock"><view class="xr-dock-summary xr-booking-selection"><text>{{form.date?calendarLabel(form.date):'请选择日期'}}</text><text>{{form.time||'请选择时间'}}</text></view><button class="xr-button xr-button-primary" :disabled="busy||subscriptionPending||loading||!!error||!bookingAvailable||!bookingStoreEnabled||!bookingReady" @click="book">{{busy?'预约中…':'确认预约'}}</button></view>
      </template>
    </template>

    <template v-else-if="page==='discover'">
      <view class="xr-discover-hero" :style="{backgroundImage:'url('+(config.pointsBanner||ui.silk)+')'}"><text class="xr-editorial">每次到店，<text class="xr-heading-line">都有小小期待</text></text><text class="xr-caption">让用心照顾，成为日常</text></view>
      <view class="xr-points-strip xr-gutter"><button @click="open('points')"><text>我的积分</text><text class="xr-stat-value">{{me.id?(me.points||0):'—'}}</text></button><button class="xr-soft-label" @click="open('sign')"><UiIcon name="calendar" tone="rose" :size="30"/>{{me.id&&me.lastSign===today?'今日已签到':'签到领积分'}}</button></view>
      <view class="xr-quick-grid xr-points-shortcuts"><button class="xr-quick" @click="open('sign')"><view class="xr-quick-circle"><UiIcon name="calendar" tone="light" :size="44"/></view><text>每日签到</text></button><button class="xr-quick" @click="open('points')"><view class="xr-quick-circle"><UiIcon name="document" tone="light" :size="44"/></view><text>积分明细</text></button><button class="xr-quick" @click="open('redemptions')"><view class="xr-quick-circle"><UiIcon name="gift" tone="light" :size="44"/></view><text>兑换记录</text></button></view>
      <view class="xr-panel xr-gutter"><view class="xr-section-heading"><text>积分商城</text><button class="xr-text-button" @click="open('legal','?type=pointsRules')">积分规则 <UiIcon name="chevron" :size="24"/></button></view><view v-if="rows.length" class="xr-reward-grid"><view v-for="reward in rows" :key="reward.id" class="xr-reward-card"><ProductVisual :product="reward"/><text class="xr-product-name">{{reward.name}}</text><text class="xr-price">{{reward.points}}<text class="xr-caption"> 积分</text></text><button class="xr-button xr-button-primary xr-button-small" :disabled="busy||loading||!!error||Number(reward.stock)<=0||(!!me.id&&Number(me.points)<Number(reward.points))" @click="redeemReward(reward)">{{Number(reward.stock)<=0?'暂时缺货':me.id&&Number(me.points)<Number(reward.points)?'积分不足':'立即兑换'}}</button></view></view><EmptyState v-else-if="!loading" icon="gift" title="奖品正在准备中" description="上架后可使用积分兑换" compact/></view>
      <button class="xr-promo-strip xr-gutter" :style="{backgroundImage:'url('+ui.room+')'}" @click="openVip"><view><text class="xr-editorial">VIP服务套餐</text><text class="xr-tiny">专属护理 · 按次预约</text></view><UiIcon name="chevron" :size="30"/></button><button class="xr-promo-strip xr-gutter" :style="{backgroundImage:'url('+ui.silk+')'}" @click="open('activities')"><view><text class="xr-editorial">近期活动</text><text class="xr-tiny">更多门店礼遇，敬请期待</text></view><UiIcon name="chevron" :size="30"/></button>
    </template>

    <template v-else-if="page==='sign'">
      <view class="xr-sign-hero" :style="{backgroundImage:'url('+ui.silk+')'}"><text class="xr-editorial">今天，也记得照顾自己</text><text class="xr-caption">每一份坚持，都是更美的自己</text><button class="xr-text-button" @click="open('legal','?type=pointsRules')">积分规则 <UiIcon name="chevron" :size="24"/></button></view>
      <view class="xr-points-balance xr-gutter"><text>我的积分</text><text class="xr-stat-value">{{me.id?(me.points||0):'—'}}</text></view><view class="xr-sign-card xr-panel xr-gutter"><text class="xr-editorial">已连续签到 <text class="xr-price">{{currentSignStreak}}</text> 天</text><text class="xr-caption">{{me.lastSign===today?'今日已获得':'每日签到可获得'}} {{config.signPoints||100}} 积分</text><button class="xr-button xr-button-primary" :disabled="busy||loading||!!error||me.lastSign===today" @click="signIn"><UiIcon v-if="me.lastSign===today" name="check-circle" tone="light" :size="36"/>{{busy?'签到中…':me.lastSign===today?'今日已签到':'立即签到 +'+(config.signPoints||100)}}</button><text class="xr-tiny xr-muted">每个北京时间自然日可签到一次</text></view><view class="xr-panel xr-gutter"><view class="xr-section-heading"><text>近期签到记录</text></view><view class="xr-sign-days"><view v-for="day in recentSignDays" :key="day.date" :class="{'is-signed':day.signed,'is-today':day.today}"><view><text v-if="day.signed" class="xr-check is-checked">✓</text><text v-else class="xr-check"/><text>{{day.signed?'+'+(config.signPoints||100):'—'}}</text></view><text>{{day.label}}</text></view></view></view><view class="xr-gutter xr-space-top"><button class="xr-button xr-button-primary" @click="switchTab('discover')">去积分商城</button></view>
    </template>

    <template v-else-if="page==='points'">
      <view class="xr-points-balance xr-gutter" :style="{backgroundImage:'url('+ui.silk+')'}"><text>我的积分</text><text class="xr-stat-value">{{me.id?(me.points||0):'—'}}</text></view><view class="xr-ledger-stats xr-panel xr-gutter"><view><text class="xr-caption">累计收入</text><text>{{pointsEarned}}</text></view><view><text class="xr-caption">累计支出</text><text>{{pointsSpent}}</text></view></view><view class="xr-panel xr-gutter"><view class="xr-tabs"><button v-for="(label,index) in ['全部','收入','支出']" :key="label" :class="{'is-active':tab===index}" @click="tab=index">{{label}}</button></view><view v-for="row in pointRows" :key="row.id" class="xr-ledger-row"><view class="xr-ledger-icon"><UiIcon :name="row.amount>0?'clock':'gift'" :size="34"/></view><view><text>{{row.name}}</text><text class="xr-caption">{{shortDate(row.createdAt)}}</text></view><text :class="['xr-ledger-amount',{'xr-price':row.amount>0}]">{{row.amount>0?'+':''}}{{row.amount}}</text></view><EmptyState v-if="!loading&&!pointRows.length" icon="document" title="暂无积分记录" description="签到与兑换产生的积分变动会显示在这里" compact/></view><view class="xr-footnote">积分变动以实际记录为准</view>
    </template>

    <template v-else-if="page==='redemptions'">
      <view v-if="successRedemption" class="xr-redemption-success"><view class="xr-success-symbol"><UiIcon name="check" tone="rose" :size="76"/></view><text class="xr-editorial">兑换成功</text><text class="xr-caption">感谢你的参与与支持</text><view class="xr-points-strip"><text>剩余积分</text><text class="xr-price">{{me.points||0}}</text></view></view>
      <view v-for="record in rows.slice().reverse()" :key="record.id" class="xr-panel xr-gutter xr-redemption-record"><view class="xr-between"><view><text class="xr-product-name">{{record.name}}</text><text class="xr-caption">{{shortDate(record.createdAt)}}</text></view><text class="xr-badge xr-badge-rose">已兑换</text></view><view class="xr-key-value"><text>消耗积分</text><text class="xr-price">{{record.points}} 积分</text></view></view>
      <template v-if="!loading&&!rows.length"><EmptyState icon="gift" title="暂无兑换记录" description="兑换成功后，记录会显示在这里" action="去积分商城" @action="switchTab('discover')"/><view class="xr-panel xr-gutter"><view class="xr-section-heading"><text>如何兑换</text></view><view class="xr-process"><view><text class="xr-step-number">1</text><text>查看奖品</text></view><UiIcon name="arrow" tone="muted" :size="24"/><view><text class="xr-step-number">2</text><text>确认积分</text></view><UiIcon name="arrow" tone="muted" :size="24"/><view><text class="xr-step-number">3</text><text>联系门店领取</text></view></view></view></template><view v-else-if="rows.length" class="xr-gutter xr-stack"><view class="xr-notice"><UiIcon name="info" tone="rose" :size="32"/><text>请联系门店确认领取方式，我们将为你安排后续服务。</text></view><button class="xr-button xr-button-primary" @click="contact()">联系门店</button><button class="xr-button xr-button-outline" @click="switchTab('discover')">返回积分商城</button></view>
    </template>

    <template v-else-if="page==='activities'">
      <view class="xr-activity-hero" :style="{backgroundImage:'url('+ui.room+')'}"><BrandMark :name="brandName" :logo="config.brandLogo" :subtitle="config.brandTagline" compact/><text class="xr-editorial">秀荣礼遇 · 慢享美好</text><text class="xr-caption">专注科技美肤，让美成为日常</text></view><view class="xr-section-heading xr-gutter"><text>近期活动</text></view>
      <view v-for="activity in (query.id?rows.filter(row=>row.id===query.id):rows)" :key="activity.id" class="xr-activity-card xr-panel xr-gutter"><image v-if="activity.image" :src="activity.image" mode="aspectFill"/><text class="xr-editorial">{{activity.name}}</text><view class="xr-prose xr-caption">{{activity.description||'活动详情请联系门店了解'}}</view><view v-if="activity.startAt||activity.endAt" class="xr-soft-label">{{activity.startAt||'即日起'}} 至 {{activity.endAt||'另行通知'}}</view><button v-if="activityProduct(activity)" class="xr-button xr-button-primary" @click="productPage(activityProduct(activity))">查看商品与方案</button><button v-else class="xr-button xr-button-outline" @click="contact()">联系门店了解详情</button></view>
      <view v-if="!rows.length&&!loading" class="xr-panel xr-gutter"><EmptyState icon="gift" title="暂无进行中的活动" description="新活动将在这里展示" compact/></view><view v-if="vipProducts.length" class="xr-section-heading xr-gutter"><text>VIP服务套餐</text></view><view class="xr-gutter"><button v-for="(product,index) in vipProducts" :key="product.id" class="xr-vip-offer" @click="productPage(product)"><view :class="['xr-tier-symbol','xr-tier-'+index]"><UiIcon name="crown" tone="rose" :size="64"/><text>XIURONG</text></view><view><text class="xr-product-name">{{product.name}}</text><text class="xr-caption">按方案选择，分次预约</text><text class="xr-price">¥{{price(product.price)}}</text></view><text class="xr-small-cta">查看方案</text></button></view>
    </template>

    <template v-else-if="page==='share'&&config.marketingEnabled===false"><EmptyState icon="share" title="门店暂未开放邀请分享" description="已产生的邀请和收益仍可在个人中心查看"/></template>
    <template v-else-if="page==='share'">
      <view class="xr-share-poster xr-gutter"><view class="xr-share-cover" :style="{backgroundImage:'url('+ui.room+')'}"><BrandMark :name="brandName" :logo="config.brandLogo" :subtitle="config.brandTagline" compact/><text class="xr-editorial">把美好，<text class="xr-heading-line">分享给朋友</text></text><text class="xr-caption">让更多人遇见更美的自己</text></view><view class="xr-share-card"><image v-if="shareImage" :src="shareImage" mode="aspectFit" class="xr-share-code" show-menu-by-longpress @click="previewShare" @longpress="handleShareLongpress"/><EmptyState v-else icon="code" :title="loading?'分享码加载中…':me.id?'分享码暂未生成':'登录后查看分享码'" :description="me.id?'请检查网络后重新加载':'好友通过邀请入口注册后建立邀请关系'" :action="loading?'':me.id?'重新加载':'去登录'" compact @action="me.id?refresh():open('login')"/><button class="xr-invite-code" @click="copy(inviteCode)"><text>我的邀请码</text><text>{{inviteCode||'—'}}</text><UiIcon name="copy" :size="32"/></button><view class="xr-caption xr-center">好友通过邀请入口注册后建立邀请关系</view></view></view><view class="xr-gutter xr-stack xr-space-top">
      <!-- #ifdef MP-WEIXIN -->
      <button class="xr-button xr-button-primary" open-type="share">转发给好友</button>
      <!-- #endif -->
      <button class="xr-button xr-button-outline" :disabled="!inviteCode" @click="copy(inviteCode)">复制邀请码</button><button class="xr-text-button" :disabled="!shareImage" @click="previewShare">查看分享码 <UiIcon name="chevron" :size="26"/></button></view>
    </template>

    <template v-else-if="page==='shares'">
      <view class="xr-invites-hero" :style="{backgroundImage:'url('+ui.silk+')'}"><text class="xr-editorial">已邀请 <text class="xr-price">{{rows.length}}</text> 位</text><text class="xr-caption">与美好同行，让更多人遇见更好的自己</text></view><view v-for="(row,index) in rows" :key="row.id||index" class="xr-invite-row xr-panel xr-gutter"><view class="xr-generic-avatar"><UiIcon name="user" tone="muted" :size="42"/></view><view><text class="xr-product-name">{{row.name||'微信好友'}}</text><text class="xr-caption">邀请注册</text></view><view><text class="xr-tiny xr-muted">{{shortDate(row.createdAt)}}</text><text class="xr-badge xr-badge-rose">已注册</text></view></view><EmptyState v-if="!loading&&!rows.length" icon="share" title="还没有邀请记录" description="把美好分享给朋友，邀请记录会显示在这里" compact/><view class="xr-panel xr-gutter"><view class="xr-section-heading"><UiIcon name="document" tone="rose" :size="34"/><text>邀请说明</text></view><view class="xr-prose xr-caption">邀请关系随新用户注册建立；奖励记录可在我的收益中查看。</view></view><view class="xr-gutter xr-stack"><button class="xr-button xr-button-primary" @click="open('earnings')">查看我的收益</button><button class="xr-button xr-button-outline" @click="open('share')">继续邀请</button></view>
    </template>

    <template v-else-if="page==='earnings'"><IncomeDashboard :records="rows" :summary="incomeSummary" :config="config" :loading="loading" :error="!!error"/></template>

    <template v-else-if="page==='alliances'">
      <view class="xr-alliance-hero" :style="{backgroundImage:'url('+ui.silk+')'}"><text class="xr-editorial">生活里的美好，<text class="xr-heading-line">相伴而来</text></text><text class="xr-caption">优质生活 · 合作共享</text></view><view class="xr-section-heading xr-gutter"><text>合作商家</text></view><view v-for="merchant in rows" :key="merchant.id" class="xr-merchant-card xr-panel xr-gutter"><image v-if="merchant.image" :src="merchant.image" mode="aspectFill"/><view><text class="xr-product-name">{{merchant.name}}</text><text class="xr-prose xr-caption">{{merchant.description||'门店介绍与服务信息'}}</text><button v-if="merchant.phone" class="xr-button xr-button-primary xr-button-small" @click="call(merchant.phone)">联系商家</button></view></view><template v-if="!loading&&!rows.length"><EmptyState icon="store" title="暂无合作商家" description="商家上架后将在这里展示"/><view class="xr-gutter"><button class="xr-button xr-button-primary" @click="contact()">联系门店</button><button v-if="activeStore.phone" class="xr-text-button xr-merchant-phone" @click="call(activeStore.phone)"><UiIcon name="phone" tone="rose" :size="32"/>{{activeStore.phone}}</button></view></template>
    </template>

    <template v-else-if="page==='about'">
      <view class="xr-about-hero"><BrandMark :name="brandName" :logo="config.brandLogo" :subtitle="config.brandTagline" tagline/><image :src="ui.room" mode="aspectFill"/></view><view class="xr-menu xr-panel xr-gutter"><view class="xr-menu-row"><text>小程序版本</text><text class="xr-caption">{{appVersion}}</text></view><button class="xr-menu-row" @click="open('legal','?type=agreement')"><text>用户服务协议</text><UiIcon name="chevron" :size="28"/></button><button class="xr-menu-row" @click="open('legal','?type=privacy')"><text>隐私政策</text><UiIcon name="chevron" :size="28"/></button></view><view v-if="config.customerQr" class="xr-panel xr-gutter"><view class="xr-section-heading"><text>客服微信</text></view><image class="xr-customer-qr" :src="config.customerQr" mode="aspectFit" show-menu-by-longpress @click="previewStore({gallery:[config.customerQr]},0)"/><text class="xr-caption xr-center">长按识别，或点击查看大图</text></view><view class="xr-help xr-gutter"><text class="xr-editorial">需要帮助</text><text class="xr-caption">预约与订单问题，可联系服务门店</text><button class="xr-button xr-button-primary" open-type="contact" session-from="about" @click="!nativeDevice&&contact()"><UiIcon name="headset" tone="light" :size="36"/>联系在线客服</button><button class="xr-button xr-button-outline" @click="contact()"><UiIcon name="phone" :size="34"/>拨打门店电话 <text v-if="activeStore.phone" class="xr-price">{{activeStore.phone}}</text></button></view>
    </template>

    <template v-else-if="page==='legal'">
      <view v-if="query.type!=='pointsRules'" class="xr-tabs xr-gutter"><button :class="{'is-active':query.type!=='privacy'}" @click="query.type==='privacy'&&open('legal','?type=agreement')">用户服务协议</button><button :class="{'is-active':query.type==='privacy'}" @click="query.type!=='privacy'&&open('legal','?type=privacy')">隐私政策</button></view><view class="xr-legal xr-gutter"><text class="xr-editorial">{{legalTitle}}</text><view v-if="legalCopy" class="xr-prose">{{legalCopy}}</view><EmptyState v-else-if="!loading" icon="document" title="暂时无法加载内容" description="请重新加载，或联系门店了解详情" action="重新加载" compact @action="refresh"/></view>
    </template>

    <view v-if="isTab" class="xr-tabbar" role="navigation"><button v-for="tabItem in mainTabs" :key="tabItem.page" :class="['xr-tab-item',{'is-active':page===tabItem.page}]" :aria-label="tabItem.name" @click="switchTab(tabItem.page)"><UiIcon :name="tabItem.page==='mall'?'bag':tabItem.page==='discover'?'compass':tabItem.page==='mine'?'user':'home'" :tone="page===tabItem.page?'ink':'muted'" :size="43"/><text>{{tabItem.name}}</text><view v-if="page===tabItem.page" class="xr-tab-active-dot"/></button></view>

    <view v-if="sheet&&product" class="xr-overlay" @click="!busy&&(sheet=false)"><view class="xr-sheet" role="dialog" aria-modal="true" aria-label="选择规格" @click.stop><view class="xr-sheet-handle"/><view class="xr-section-heading"><text>选择规格</text><button class="xr-icon-button" aria-label="关闭" @click="sheet=false"><UiIcon name="close" :size="34"/></button></view><view class="xr-sheet-product"><ProductVisual :product="product"/><view><text class="xr-product-name">{{product.name}}</text><text class="xr-price xr-price-large">¥{{price(unitPrice)}}</text></view></view><view class="xr-spec-options"><template v-if="product.skus?.length"><button v-for="sku in product.skus" :key="sku.id" :class="['xr-spec-option',{'is-selected':skuId===sku.id}]" :disabled="sku.enabled===false||sku.stock<1" @click="skuId=sku.id;spec='single';quantity=Math.min(quantity,sku.stock)"><text :class="['xr-check',{'is-checked':skuId===sku.id}]">{{skuId===sku.id?'✓':''}}</text><text>{{sku.name}}</text><text class="xr-price">¥{{price(sku.price)}}</text><text v-if="sku.enabled===false||sku.stock<1" class="xr-tiny">售罄</text></button></template><template v-else><button :class="['xr-spec-option',{'is-selected':spec==='single'}]" @click="spec='single'"><text :class="['xr-check',{'is-checked':spec==='single'}]">{{spec==='single'?'✓':''}}</text><text>{{product.kind==='goods'?'1件':'单次 · 1次'}}</text><text class="xr-price">¥{{price(product.memberPrice??product.price)}}</text></button><button v-if="product.coursePrice!=null" :class="['xr-spec-option',{'is-selected':spec==='course'}]" @click="spec='course'"><text :class="['xr-check',{'is-checked':spec==='course'}]">{{spec==='course'?'✓':''}}</text><text>疗程</text><text class="xr-price">¥{{price(product.coursePrice)}}</text></button></template></view><view class="xr-quantity-row"><text>购买数量</text><view class="xr-quantity"><button :disabled="quantity<=1" aria-label="减少数量" @click="quantity--"><UiIcon name="minus" :size="30"/></button><text>{{quantity}}</text><button :disabled="quantity>=availableStock||quantity>=99" aria-label="增加数量" @click="quantity++"><UiIcon name="plus" :size="30"/></button></view></view><view v-if="product.kind==='service'" class="xr-footnote">{{selectedSku?.serviceSessions?'本规格包含'+selectedSku.serviceSessions+'次服务，可分次预约使用':'到店服务按项目与可用次数预约'}}</view><button class="xr-button xr-button-primary" :disabled="!canBuy" @click="checkout">确认规格</button></view></view>

    <view v-if="rewardToConfirm" class="xr-overlay xr-overlay-center" @click="!busy&&(rewardToConfirm=null)"><view class="xr-confirm-dialog" role="dialog" aria-modal="true" aria-label="确认兑换" @click.stop><view class="xr-dialog-symbol"><UiIcon name="gift" tone="rose" :size="72"/></view><text class="xr-editorial">确认兑换</text><text class="xr-caption">是否使用积分兑换以下商品？</text><view class="xr-confirm-reward"><ProductVisual :product="rewardToConfirm"/><view><text class="xr-product-name">{{rewardToConfirm.name}}</text><text class="xr-price">{{rewardToConfirm.points}} 积分</text></view></view><view class="xr-key-value"><text>当前积分</text><text>{{me.points||0}}</text></view><view class="xr-key-value"><text>本次扣除</text><text class="xr-price">{{rewardToConfirm.points}}</text></view><view class="xr-key-value"><text>兑换后积分</text><text class="xr-price">{{Math.max(0,Number(me.points)-Number(rewardToConfirm.points))}}</text></view><view class="xr-footnote">兑换后请联系门店确认领取。</view><view class="xr-dialog-actions"><button class="xr-button xr-button-outline" :disabled="busy" @click="rewardToConfirm=null">取消</button><button class="xr-button xr-button-primary" :disabled="busy" @click="confirmRedemption">{{busy?'兑换中…':'确认兑换'}}</button></view></view></view>

    <view v-if="orderToCancel" class="xr-overlay" @click="!busy&&(orderToCancel=null)"><view class="xr-sheet xr-cancel-sheet" role="dialog" aria-modal="true" aria-label="取消订单" @click.stop><button class="xr-icon-button xr-dialog-close" aria-label="关闭" :disabled="busy" @click="orderToCancel=null"><UiIcon name="close" :size="32"/></button><text class="xr-editorial">取消这笔订单？</text><text class="xr-caption">取消后如需服务，可重新下单。</text><view class="xr-dialog-actions"><button class="xr-button xr-button-outline" :disabled="busy" @click="orderToCancel=null">暂不取消</button><button class="xr-button xr-button-primary" :disabled="busy" @click="confirmCancelOrder">{{busy?'取消中…':'确认取消'}}</button></view></view></view>
  </view>
</template>
<script>
import screen from './beauty-screen.js'
import BrandMark from './BrandMark.vue'
import UiIcon from './UiIcon.vue'
import ProductVisual from './ProductVisual.vue'
import EmptyState from './EmptyState.vue'
import PackagePicker from './PackagePicker.vue'
import BookingAvailability from './BookingAvailability.vue'
import IncomeDashboard from './IncomeDashboard.vue'
// Keep registrations in the SFC: the mini-program compiler builds its native
// usingComponents map statically and cannot infer the decorated script export.
export default { ...screen, options:{virtualHost:true,styleIsolation:'shared'}, components:{BrandMark,UiIcon,ProductVisual,EmptyState,PackagePicker,BookingAvailability,IncomeDashboard} }
</script>
